### 📚 শব্দার্থ ও টীকা : চণ্তাল- চাড়াল, হিন্দু বর্ণব্যবস্থায় নিম্নবর্ণের লোক। বোধন-বাঁশি- বোধ জাগিয়ে
তোলার বাশি। দৈন্য- দারিদ্ৰ্য,দীনতা ।

