# ১৪তম অধ্যায়: নিমগাছ (বনফুল)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: বনফুল*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : প্রকৃত নাম বলাইচাদ মুখোপাধ্যায় । বিহারের পূর্ণিয়ার অন্তর্গত মণিহার গ্রামে ১৮৯৯ খিষ্টাব্দের
১৯শে জুলাই তিনি জন্মগ্রহণ করেন। বনফুল পূর্ণিয়ার সাহেবগঞ্জ ইংরেজি উচ্চ বিদ্যালয় থেকে ম্যাট্রিক,
হাজারীবাগের সেন্ট কলম্বাস কলেজ থেকে আইএসসি এবং পাটনা মেডিক্যাল কলেজ থেকে
এমবি পাশ করেন। মেডিক্যাল অফিসার পদে চাকরির মাধ্যমে বনফুলের কর্মজীবন শুরু । ১৯১৮ খিষ্টাব্দে
শনিবারের চিঠি'তে ব্যঙ্গ-কবিতা ও প্যারোডি লিখে তার সাহিত্য অঙ্গনে প্রবেশ। প্রবাসী পত্রিকায় তিনি একপাতা-
আধপাতার গল্প লিখতেন । গল্পগুলো আকারে ক্ষুদ্র, অথচ বক্তব্যে তাৎপর্ষপূর্ণ। তার উল্লেখযোগ্য গল্পগ্রন্থ :
উপাদান তার গল্প ও উপন্যাসে নিপুণভাবে প্রকাশিত হয়েছে। বনফুলের উল্লেখযোগ্য উপন্যাস হলো: তৃণখণ,
কিছুক্ষণ, দ্বৈরথ, জঙ্গম ইত্যাদি । বিভিন্ন পুরস্কারসহ তিনি পদ্মভূষণ উপাধি লাভ করেন । ১৯৭৯ খিষ্টাব্দের ৯ই

ফেকুয়ারি বনফুল কলকাতায় মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (গদ্য)

নিমগাছ

বনফুল



কেউবা ভাজছে গরম তেলে।

খোস দাদ হাজা চুলকানিতে লাগাবে ।

চর্মরোগের অব্যর্থ মহৌষধ ।

কচি পাতাগুলো খায়ও অনেকে ।

কিম্বা ভেজে বেগুন-সহযোগে।

কচি ডালগুলো ভেঙে চিবোয় কত লোক ... দাত ভালো থাকে । কবিরাজরা প্রশংসায় পঞ্চমুখ ।
বলে- নিমের হাওয়া ভালো, থাক্‌, কেটো না।'

কাটে না, কিন্ত যতুও করে না।

আবর্জনা জমে এসে চারিদিকে ।

শান দিয়ে বাধিয়েও দেয় কেউ- সে আর-এক আবর্জনা ।

হঠাৎ একদিন একটা নতুন ধরনের লোক এলো ।

মুগ্ধদৃষ্টিতে চেয়ে রইল নিমগাছের দিকে ছাল তুললে না,পাতা ছিড়লে না, ডাল ভাঙলে না,

মুগ্ধদৃষ্টিতে চেয়ে রইল শুধু।
বলে উঠল,-“বাহ্‌, কী সুন্দর পাতাগুলি ... কী রূপ! থোকা-থোকা ফুলেরই বাকী বাহার... একবঝীক

নক্ষত্র নেমে এসেছে যেন নীল আকাশ থেকে সবুজ সায়রে | বাহ্‌-ঃ
খানিকক্ষণ চেয়ে থেকে চলে গেল।

নিমগাছটার ইচ্ছে করতে লাগল লোকটার সঙ্গে চলে যায়। কিন্তু পারলে না। মাটির ভিতরে
শিকড় অনেক দূরে চলে গেছে। বাড়ির পিছনে আবর্জনার স্তূপের মধ্যেই দাড়িয়ে রইল সে।

ওদের বাড়ির গৃহকর্ম-নিপুণা লক্ষ্মীবউটার ঠিক এক দশা ।

---

### 📚 শব্দার্থ ও টীকা : ছাল - বাকল, এখানে নিমগাছের বাকল | শিলে পেষা - শিল-পাটায় বাটা।
অব্যর্থ - যা বিফল হবে না। পাতাগুলো খায়ও _- নিমের কচিপাতা খেলে মানুষের শরীরে রোগ
প্রতিরোধ ক্ষমতা বাড়ে। শান দিয়ে বাধানো - এখানে ইট ও সিমেন্ট দিয়ে বাঁধানো বোঝাচ্ছে।
কবিরাজ - যিনি গাছগাছালি পরিশোধন করে মনুষ্যরোগের চিকিৎসা করেন। কবি - যিনি কবিতা
লেখেন । শিকড় অনেক দূর চলে গেছে - প্রতীকাশ্রয়ে বর্ণিত। নিমগাছের শিকড় মাটির গভীরে
প্রবেশ করে এবং চারিদিকে বিস্তৃতও হয়। লক্ষ্মী বউটার প্রতীক যেহেতু নিমগাছ সেহেতু নিমগাছের
শিকড়ের সঙ্গে বউয়ের সংসারের জালে চারিদিকে আবদ্ধ হওয়াকে বোঝানো হয়েছে।

---

### 📝 পাঠ-পরিচিতি : বলাইচাদ মুখোপাধ্যায়ের (বনফুল) অদৃশ্যলোক গ্রন্থের অন্তর্ভূক্ত “নিমগাছ'
গল্প । এই গল্পের সংক্ষিপ্ত অবয়বের মধ্যে লেখক বিপুল বক্তব্য উপস্থাপনে যে দক্ষতার পরিচয় দিয়েছেন
তা বাংলা সাহিত্যে বিরল । নিমগাছের বর্ণনা, এর পাতা, বাকল, ছায়া ইত্যাদির বাহ্যিক উপকারিতা
কবিতার মতো বর্ণনা করা হয়েছে এই গল্পে। কবিরাজ তার চিকিৎসার কাজে, সাধারণ মানুষ
প্রাত্যহিক প্রয়োজনে নিমগাছকে অনবরত ব্যবহার করে থাকে । কিন্তু কেউ এই গাছের সামান্যও
যত্বু নেয় না। একজন কবি একদিন নিমগাছের গুণ ও রূপের প্রশংসা করে । নিমগাছের ভালো লাগে
এ লোককে এবং সে তার সঙ্গে চলে যেতে চায় । কিন্ত মাটির গভীরে তার শিকড় । গাছটি যেতে পারে
না। আসলে গাছ তো চলতে পারে না। এটি একটি প্রতীকী গল্প । প্রকৃতপক্ষে, “নিমগাছ' গল্পটির নিমগাছ
ও সামাজিক গুরুত্ব উপলব্ধি করার ইঙ্গিত দেয় গল্পটি ।

কর্ম-অনুশীলন
১। নিমগাছের গুণাগ্তণের একটি তালিকা তৈরি করো ।

২। তোমার এলাকায় নিমগাছ রোপণের কর্মসূচি নেওয়া দরকার । এ কাজ করার জন্য তোমরা কী কী
করবে?



নমুনা প্রন
বহুনির্বাচনি প্রশ্ন
১। নিমগাছের ছাল নিয়ে লোকজন কী কাজে লাগায়?
ক. সিদ্ধ করে খায় খ. ভিজিয়ে খায়
গ. শুকিয়ে খায় ঘ. রান্না করে খায়
২। বাড়ির পাশে গজালে বিজ্ঞরা খুশি হয় কেন?
ক. এটা দেখতে সুন্দর খ. এটা উপকারী
গ. এটা পরিবেশ-বান্ধব ঘ. এটা আকারে ছোট
নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

গত আট বছর ধরে কৃষক গফুরের চাষাবাদের প্রধান অবলম্বন ছিল প্রিয় ষাড় মহেশ । বয়সের কারণে
মহেশ এখন আগের মতো কাজ করতে না পারলেও তার প্রতি গফুরের স্রেহ এতটুকু কমেনি । পরিবারের

সদস্য এবং প্রতিবেশীদের পরামর্শে মহেশকে বিক্রি না করে তাকে সন্তানত্রেহে লালন করতে থাকে দরিদ্র
গফুর ।
ক. উপকারী খ. সর্বংসহা
গ. আত্মত্যাগী ঘ. স্রেহ-কাঙাল
