# ১৫তম অধ্যায়: শিক্ষা ও মনুষ্যত্ব (মোতাহের হোসেন চৌধুরী)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: মোতাহের হোসেন চৌধুরী*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: মোতাহের হোসেন চৌধুরী ১৯০৩ খিষ্টাব্দের ১লা এপ্রিল জনুগ্রহণ করেন। তাঁর পৈতৃক
নিবাস লক্ষ্মীপুর জেলার কাঞ্চনপুর গ্রামে । তিনি ঢাকা বিশ্ববিদ্যালয় থেকে বাংলায় এমএ পাশ করেন।
কর্মজীবনে তিনি বাংলা ভাষা ও সাহিত্যের অধ্যাপক ছিলেন। একজন সংস্কৃতিবান ও মার্জিত রুচিসম্পন্ন
ব্যক্তি হিসেবে তিনি খ্যাত ছিলেন । ঢাকা থেকে প্রকাশিত “শিখা* পত্রিকার সঙ্গে তিনি যুক্ত ছিলেন। তাঁর
প্রবন্ধগ্রন্থ সংস্কৃতি কথা বাংলা সাহিত্যের মননশীল প্রবন্ধ-ধারায় একটি উল্লেখযোগ্য সংযোজন । তাঁর
মৃত্যুর পর গ্রন্থটি গ্রকাশিত হয়। সভ্যতা ও সুখ তাঁর দুটি অনুবাদগ্রন্থ। ১৯৫৬ খিষ্টাব্দের ১৮ই সেপ্টেম্বর
তিনি পরলোকগমন করেন |

---

## 📖 মূল পাঠ (গদ্য)

শিক্ষা ও মনুষ্যত
মোতাহের হোসেন চৌধুরী



মানুষের জীবনকে একটি দোতলা ঘরের সঙ্গে তুলনা করা যেতে পারে। জীবসত্তা সেই ঘরের নিচের
তলা, আর মানবসত্তা বা মনুষ্যত্‌ ওপরের তলা। জীবসত্তার ঘর থেকে মানবসত্তার ঘরে উঠবার মই
হচ্ছে শিক্ষা । শিক্ষাই আমাদের মানবসত্তার ঘরে নিয়ে যেতে পারে । অবশ্য জীবসত্তার ঘরেও সে কাজ
করে; ক্ষুতপিপাসার ব্যাপারটি মানবিক করে তোলা, তার অন্যতম কাজ । কিন্তু তার আসল কাজ হচ্ছে
মানুষকে মনুষ্যত্বলোকের সঙ্গে পরিচয় করিয়ে দেওয়া । অন্য কথায়, শিক্ষার যেমন প্রয়োজনের
দিক আছে, তেমনি অপ্রয়োজনীয় দিকও আছে । আর অপ্রয়োজনের দিকই তার শ্রেষ্ঠ দিক। সে
আস্বাদন করা যায়। শিক্ষার এ দিকটা যে বড়ো হয়ে ওঠে না, তার কারণ ভুল শিক্ষা ও নিচের
তলায় বিশৃঙ্খলা জীবসত্তার ঘরটি এমন বিশৃঙ্খল হয়ে আছে যে, হতভাগ্য মানুষকে সব সময়ই
সে সম্বন্ধে সচেতন থাকতে হয়। ওপরের তলার কথা সে মনেই আনতে পারে না। অর্থচিন্তার নিগড়ে
সকলে বন্দি। ধনী-দরিদ্র সকলেরই অন্তরে সেই একই ধ্বনি উথথিত হচ্ছে : চাই, চাই, আরও চাই।
তাই অন্নচিন্তা তথা অর্থচিন্তা থেকে মানুষ মুক্তি না পেলে, অর্থসাধনাই জীবনসাধনা নয়- একথা
মানুষকে ভালো করে বোঝাতে না পারলে মানবজীবনে শিক্ষা সোনা ফলাতে পারবে না । ফলে শিক্ষার
সুফল হবে ব্যক্তিগত, এখানে সেখানে দুএকটি মানুষ শিক্ষার আসল উদ্দেশ্যটি উপলব্ধি করতে
পারবে, কিন্তু বেশির ভাগ লোকই যে তিমিরে সে তিমিরেই থেকে যাবে।

তাই অন্নচিন্তার নিগড় থেকে মানুষকে মুক্তি দেওয়ার যে চেষ্টা চলেছে তা অভিনন্দনযোগ্য । কিন্তু লক্ষ্য
সম্বন্ধে সচেতন না থাকলে সে চেষ্টাও মানুষকে বেশি দূর নিয়ে যেতে পারবে বলে মনে হয় না।
কারারুদ্ধ আহারতৃপ্ত মানুষের মূল্য কতটুকু? প্রচুর অন্নবস্ত্র পেলে আলো হাওয়ার স্বাদবঞ্চিত মানুষ
কারাগারকেই স্বর্গতুল্য মনে করে। কিন্ত তাই বলে যে তা সত্য সত্যই স্বর্গ হয়ে যাবে, তা নয়।
বাইরের আলো হাওয়ার স্বাদ পাওয়া মানুষ প্রচুর অন্নবস্ত্র পেলেও কারাগারকে কারাগারই মনে করবে,
এবং কী করে তা থেকে মুক্তি পাওয়া যায় তাই হবে তার একমাত্র চিন্তা । আকাশ-বাতাসের ডাকে
যে পক্ষী আকুল, সে কি খাঁচায় বন্দি হবে সহজে দানাপানি পাওয়ার লোভে? অন্নবস্ত্ের প্রাচুর্যের চেয়েও
মুক্তি বড়, এই বোধটি মানুষের মনুষ্যত্ব পরিচায়ক ।


চিন্তার স্বাধীনতা, বুদ্ধির স্বাধীনতা, আত্মপ্রকাশের স্বাধীনতা যেখানে নেই সেখানে মুক্তি নেই।
মানুষের অন্নবস্ত্রের সমস্যা সমাধানের চেষ্টা করতে হবে এই মুক্তির দিকে লক্ষ রেখে। ক্ষুতপিপাসায়
কাতর মানুষটিকে তৃপ্ত রাখতে না পারলে আত্মার অমৃত উপলব্ধি করা যায় না বলেই ক্ষুৎ্পপাসার
তৃপ্তির প্রয়োজন । একটা বড়ো লক্ষ্যের দিকে দৃষ্টি রেখেই অন্নবস্ত্রের সমাধান করা ভালো, নইলে
আমাদের বেশি দূর নিয়ে যাবে না।

তাই মুক্তির জন্য দুটি উপায় অবলম্বন করতে হবে । একটি অন্নবস্ত্রের চিন্তা থেকে মানুষকে মুক্তি
দেওয়ার চেষ্টা, আরেকটি শিক্ষাদীক্ষার দ্বারা মানুষকে মনুষ্য স্বাদ পাওয়ানোর সাধনা । এ উভয়বিধ
চেষ্টার ফলেই মানবজীবনের উন্নয়ন সম্ভব । শুধু অন্নবস্ত্রের সমস্যাকে বড়ো করে তুললে সুফল পাওয়া
যাবে না। আবার শুধু শিক্ষার ওপর নির্ভর করলে সুদীর্ঘ সময়ের দরকার । মনুষ্যত্রে স্বাদ না পেলে
অন্নবস্ত্রের চিন্তা থেকে মুক্তি পেয়েও মানুষ যেখানে আছে সেখানেই পড়ে থাকতে পারে; আবার
শিক্ষাদীক্ষার মারফতে মনুষ্যত্রে স্বাদ পেলেও অন্নবস্ত্রের দুশ্চিন্তায় মনুষ্যত্রে সাধনা ব্যর্থ
হওয়া অসম্ভব নয়।

কোনো ভারী জিনিসকে ওপরে তুলতে হলে তাকে নিচের থেকে ঠেলতে হয়, আবার ওপর থেকে
টানতেও হয়; শুধু নিচের থেকে ঠেললে তাকে আশানুরূপ ওপরে ওঠানো যায় না। মানব উন্নয়নের
ব্যাপারে শিক্ষা সেই ওপর থেকে টানা, আর সুশৃঙ্খল সমাজ-ব্যবস্থা নিচের থেকে ঠেলা । অনেকে মিলে
খুব জোরে ওপরের থেকে টানলে নিচের ঠেলা ছাড়াও কোনো জিনিস ওপরে ওঠানো যায়- কিন্তু
শুধু নিচের ঠেলায় বেশিদূর ওঠানো যায় না। তেমনি আপ্রাণ প্রচেষ্টার ফলে শিক্ষার দ্বারাই জীবনের
মনুষ্যত্রে স্বাদ পেলে অনন-বস্ত্রের সমাধান সহজেই হতে পারে । কেননা অন্ন-বস্ত্রের অব্যবস্থার মূলে লোভ,
আর শিক্ষাদীক্ষার ফলে মানুষ উপলব্ধি করতে পারে, “লোভে পাপ, পাপে মৃত্যু” কথাটা বুলিমাত্র নয়,
সত্য । লোভের ফলে যে মানুষের আত্মিক মৃত্যু ঘটে, অনুভূতির জগতে সে ফতুর হয়ে পড়ে, শিক্ষা
মানুষকে সে-কথা জানিয়ে দেয় বলে মানুষ লোভের ফীদে ধরা দিতে ভয় পায় । ছোটো জিনিসের মোহে
বড়ো জিনিস হারাতে যে দুঃখ বোধ করে না, সে আর যাই হোক, শিক্ষিত নয়। শিক্ষা তার বাইরের
ব্যাপার, অন্তরের ব্যাপার হয়ে ওঠে নি। লেফাফাদুরস্তি আর শিক্ষা এক কথা নয়। শিক্ষার আসল কাজ
জ্ঞান পরিবেশন নয়, মূল্যবোধ সৃষ্টি; জ্ঞান পরিবেশন মূল্যবোধ সৃষ্টির উপায় হিসেবেই আসে । তাই
যেখানে মূল্যবোধের মূল্য পাওয়া হয় না, সেখানে শিক্ষা নেই।

শিক্ষার মারফতে মূল্যবোধ তথা মনুষ্যত্ব লাভ করা যায়; তথাপি অন্নবস্ত্রের সুব্যবস্থাও প্রয়োজনীয় ।
চেষ্টা ভালো; কিন্তু প্রাণিত্রে বাধন থেকে মুক্তি না পেলে মনুষ্যত্রে আহ্বান মানুষের মর্মে গিয়ে
নজর দিতে হলে হাটার আনন্দ উপভোগ করা যায় না, তেমনি অন্নবস্ত্ের চিন্তায় হামেশা বিব্রত হতে
হলে মুক্তির আনন্দ উপভোগ করা কঠিন হয়ে দীড়ায় । তাই দু দিক থেকেই কাজ চলা দরকার ।
বেড়িমুক্ত হয়েও মানুষ ওপরে যাওয়ার তাগিদ অনুভব করবে না, অথবা মনুষ্যত্বের আহ্বান সত্তেও
ওপরে যাওয়ার স্বাধীনতার অভাব বোধ করবে, পিঞ্জরাবদ্ধ পাখির মতো উড়বার আকাজ্কায় পাখা
ঝাপটাবে, কিন্তু উড়তে পারবে না।

---

### 📚 শব্দার্থ ও টীকা : নিগড়-শিকল, বেড়ি। তিমির-অন্ধকার। ক্ষুত্পিপাসা-ক্ষুধা ও তৃষ্ণা । ফতুর-নিঃস্ব,
সর্বস্বান্ত । লেফাফাদুরস্তি-বাইরের দিক থেকে ক্রুটিহীনতা কিন্ত ভিতরে ফীপা। বেড়ি _-শিকল,

শৃঙ্খল । হামেশী- সবসময়, সর্বক্ষণ । উন্মোচন-উন্যুক্ত করা । পিঞ্জরবদ্ধ-খাচায় বন্দি। জীবসত্তা-
জীবের অস্তিত্।

মানবসত্তা-মানুষের অস্তিত্ব । মানবসত্তা বলতে লেখক মনুষ্যত্কে বুঝিয়েছেন। শিক্ষার মাধ্যমে এই
রাখতে অধিক মনোযোগী । ফলে অর্থচিন্তা আমাদের সারাক্ষণ ব্যস্ত রাখে। অর্থচিন্তায় ব্যস্ত মানুষ
প্রকৃত মনুষ্যত্ব অর্জনে সক্ষম নয় ।

কারারুদ্ধ আহারতৃপ্ত মানুষের মূল্য কতটুকু?_ খাওয়া-পরার সমস্যা মিটে গেলেই জীবনের উন্নয়ন
সম্ভব হয় না। এ জন্য প্রয়োজন চিন্তার স্বাধীনতা, বুদ্ধির স্বাধীনতা ও আত্মপ্রকাশের স্বাধীনতা ।
শিক্ষার মাধ্যমেই এ স্বাধীনতা অর্জিত হয়।

---

### 📝 পাঠ-পরিচিতি : "শিক্ষা ও মনুষ্য” প্রবন্ধটি মোতাহের হোসেন চৌধুরীর সংস্কতি-কথা গ্রন্থের
“মনুষ্যতৃ" শীর্ষক প্রবন্ধের অংশবিশেষ । মানুষের দুটি সত্তা- একটি তার জীবসত্তা, অপরটি মানবসত্তা
বা মনুষ্যত্ব । জীবসত্তার জন্য প্রয়োজনীয় অন্নবস্ত্রের চিন্তা থেকে মুক্তি এবং শিক্ষা লাভের মাধ্যমে
মনুষ্যত্বের বিকাশ ঘটে । শিক্ষার ফলে মনুষ্যত্রে স্বাদ পেলে অন্নবস্ত্রের সমস্যার সমাধান সহজ
হয়ে ওঠে। শিক্ষার আসল কাজ মূল্যবোধ সৃষ্টি, জ্ঞান দান নয়; জ্ঞান মূল্যবোধ সৃষ্টির উপায়মাত্র ।“শিক্ষা
ও মনুষ্যত্ব" প্রবন্ধে মোতাহের হোসেন চৌধুরী শিক্ষা ও মানবিক মূল্যবোধের সম্পর্ক চিহিত করেছেন।
জ্ঞান ও অন্তরের মুক্তি ব্যক্তিকে মনুষ্যতববোধে উন্নীত হওয়ার শিক্ষা দেয়।

কর্ম-অনুশীলন

মানব মুক্তির জন্য সমাজের উপরের অংশ ও নিচের অংশের কর্তব্যগুলো নির্দেশ করো ।
