### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: মোতাহের হোসেন চৌধুরীর মতে মানব সত্তার দুই তল কী কী?**
> 💡 **উত্তর:** জীবসত্তা (খাদ্য-বস্ত্রের জৈবিক চাহিদা) হলো নিচের তলা এবং মানবসত্তা বা মনুষ্যত্ব (জ্ঞান ও আত্মিক মুক্তি) হলো উপরের তলা। শিক্ষা এই নিচের তলা থেকে উপরের তলায় ওঠার মই।

> ❓ **প্রশ্ন: কেবল জীবসত্তার চাহিদায় বন্দি থাকলে মানুষের কী ক্ষতি হয়?**
> 💡 **উত্তর:** মানুষের আত্মিক বিকাশ রুদ্ধ হয়ে যায় এবং সে লোভের দাস হয়ে খাঁচাবন্দি পাখির মতো কেবল আহার খোঁজে, কিন্তু মুক্তির আনন্দ উপলব্ধি করতে পারে না।
