# ১৬তম অধ্যায়: প্রবাস বন্ধু (সৈয়দ মুজতবা আলী)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: সৈয়দ মুজতবা আলী*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: সৈয়দ মুজতবা আলী ১৩ই সেপ্টেম্বর, ১৯০৪ খিষ্টান্দে আসামভুক্ত শ্রীহট্রের করিমগঞ্জে
জন্গ্রহণ করেন । তিনি সিলেট গভর্মেন্ট হাইস্কুল ও শান্তিনিকেতনে পড়াশোনা করেন । পরে ১৯২৬ সালে
বিশ্বভারতী থেকে ম্বাতক ডিগ্রি অর্জন করেন। আফগানিস্তানে কাবুলের কৃষিবিজ্ঞান কলেজে অধ্যাপনা
দিয়ে তাঁর কর্মজীবন শুরু হয়। এরপর বার্লিন ও বন বিশ্ববিদ্যালয়ে অধ্যয়ন করেন। ১৯৩২ সালে তিনি
ও মহীশূরের বরোদা কলেজে অধ্যাপনা করেন । তিনি ১৯৪৯ খিষ্টাব্দে বগুড়ার আজিজুল হক কলেজে
অধ্যক্ষ হিসেবে যোগদান করেন । কিন্তু পাকিস্তান সরকারের বিরুদ্ধে প্রবন্ধ লেখার অভিযোগে তাঁকে
চাকরি ছাড়তে হয়। পরে তিনি বিশ্বভারতীর রিডার নিযুক্ত হন। সৈয়দ মুজতবা আলী নিজস্ব এক
গদ্যশৈলীর নির্মাতা । বিভিন্ন ভাষায় ব্যুৎপত্তি ও অসাধারণ পাঞ্জিত্যের সংমিশ্রণে তিনি যে গদ্য রচনা
করেছেন, তা খুবই রসগ্রাহী হয়ে উঠেছে। তাঁর উল্লেখযোগ্য রচনাগুলো হলো: দেশে-বিদেশে, পঞ্চতন্ত্,
চাচা কাহিনী, ময়ূরকণ্ঠী, শবনম ইত্যাদি । তিনি ১১ই ফেব্রুয়ারি, ১৯৭৪ খিষ্টাব্দে ঢাকায় মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (গদ্য)

প্রবাস বন্ধু
সৈয়দ মুজতবা আলী



বাসা পেলুম কাবুল থেকে আড়াই মাইল দূরে খাজামোল্লা গ্রামে । বাসার সঙ্গে সঙ্গে চাকরও পেলুম ।

অধ্যক্ষ জিরার জাতে ফরাসি। কাজেই কায়দামাফিক আলাপ করিয়ে দিয়ে বললেন, “এর নাম
আবদুর রহমান। আপনার সব কাজ করে দেবে- জুতো বুরুশ থেকে খুনখারাবি।, অর্থাৎ ইনি
“হরফুন-মৌলা” বা “সকল কাজের কাজি'।

জিরার সায়েব কাজের লোক, অর্থাৎ সমস্ত দিন কোনো-না-কোনো মন্ত্রীর দপ্তরে ঝগড়া-বচসা করে
কাটান । কাবুলে এরই নাম কাজ । “ও রভোয়া, বিকেলে দেখা হবে" বলে চলে গেলেন।

কাবুল শহরে আমি দুটি নরদানব দেখেছি । তার একটি আবদুর রহমান।

পরে ফিতে দিয়ে মেপে দেখেছিলুম ছ ফুট চার ইঞ্চি । উপস্থিত লক্ষ করলুম লম্বাই মিলিয়ে চওড়াই।
দুখানা হাত হাটু পর্যন্ত নেমে এসেছে। আউুলগুলো দু কীদি মর্তমান কলা হয়ে ঝুলছে। পা দুখানা ভিডি
নৌকার সাইজ | কীধ দেখে মনে হলো, আমার বাবুর্টি আবদুর রহমান না হয়ে সে যদি আমির
আবদুর রহমান হত তবে অনায়াসে গোটা আফগানিস্তানের ভার বইতে পারত। এ কান ও কান
জোড়া মুখ- হ্যা করলে চওড়াচওড়ি কলা গিলতে পারে । এবড়ো-থেবড়ো নাক-কপাল নেই । পাগড়ি
থাকায় মাথার আকার-প্রকার ঠাহর হলো না, তবে আন্দাজ করলুম বেবি সাইজের হ্যাটও কান অবধি
পৌছবে।

রং ফর্সা, তবে শীতে গ্রীম্মে চামড়া চিরে ফেঁড়ে গিয়ে আফগানিস্তানের রিলিফ ম্যাপের চেহারা ধরেছে। দুই
গাল কে যেন থাবড়া মেরে লাল করে দিয়েছে- কিন্ত কার এমন বুকেট পাটা? রুজও তো মাখবার কথা নয়।

পরনে শিলওয়ার, কুর্তা আর ওয়াসকিট ।

ঠোট দুটি দেখতে পেলুম না । সেই যে প্রথম দিন ঘরে ঢুকে কার্পেটের দিকে নজর রেখে দীড়িয়েছিল,
শেষ দিন পর্যন্ত এ কার্পেটের অপরূপ রূপ থেকে তাকে বড়ো একটা চোখ ফেরাতে দেখিনি ।
গুরুজনদের দিকে তাকাতে নেই, আফগানিস্তানেও নাকি এই ধরনের একটা সংস্কার আছে।



ভেসে উঠেছে।

জরিপ করে ভরসা পেলুম, ভয়ও হলো। এ লোকটা ভীমসেনের মতো রান্না তো করবেই, বিপদে-
বিগড়ে যায়? তবে?

উত্তর দিল, “কোথাও না, পল্টনে ছিলুম, মেসের চার্জে । এক মাস হলো খালাস পেয়েছি ।
একগাল হাসল ।

“পোলাও, কোরমা, কাবাব, ফালুদা-।"

আমি বললুম, “তাহলে বরফ আসে কোথেকে?'

বলল, “কেন, এ পাগমানের পাহাড় থেকে ।' বলে জানলা দিয়ে পাহাড়ের বরফ দেখিয়ে দিল।

বলল, 'না সায়েব, এর অনেক নিচে বড়ো বড়ো গর্তে শীতকালে বরফ ভর্তি করে রাখা হয়। এখন
তাই খুঁড়ে তুলে গাধা বোঝাই করে নিয়ে আসা হয় ।”

থেকে সব কিছু কিনে নিয়ে এসো । রাত্তিরের রান্না আজ আর বোধ হয় হয়ে উঠবে না। কাল
দুপুরে রান্না কোরো । সকালবেলা চা দিয়ো ।”
টাকা নিয়ে চলে গেল ।

বেলা থাকতেই কাবুল রওনা দিলুম ৷ আড়াই মাইল রাস্তা মৃদুমধুর ঠান্ডায় গড়িয়ে গড়িয়ে পৌছব।
পথে দেখি এক পবর্তপ্রমাণ বোঝা নিয়ে আবদুর রহমান ফিরে আসছে। জিজ্ঞেস করলুম, “এত বোঝা
বইবার কি দরকার ছিল- একটা মুটে ভাড়া করলেই তো হত।

যা বলল, তার অর্থ এই, সে যে-মোট বইতে পারে না, সে-মোট কাবুলে বইতে যাবে কে?
ভাব দেখে বুঝলুম, অতটা তার মাথায় খেলেনি, অথবা ভাববার প্রয়োজনবোধ করেনি ।

পেলুম । আমি ফের চলতে আরম্ভ করলে বলল, “সায়েব রাত্রে বাড়িতেই খাবেন ।'

খুব বেশি দূর যেতে হলো না। লব-ই-দরিয়া অর্থাৎ কাবুল নদীর পারে পৌছতে না পৌছতেই দেখি
মশিয়ে জিরার টাঙা হাঁকিয়ে টগবগাবগ করে বাড়ি ফিরছেন।

কলেজের বড়কর্তা বা বস্‌ হিসাবে আমাকে তিনি বেশ দু-এক প্রস্থ ধমক দিয়ে বললেন, “কাবুল
শহরে নিশাচর হতে হলে যে তাগদ ও হাতিয়ারের প্রয়োজন, সে দুটোর একটাও তোমার নেই ।

না করা। বিশেষ করে যখন বসের উত্তমার্ধ তারই পাশে বসে উই, সার্তেনমী, এভিদার্মী, অর্থাৎ অতি
অবশ্য, সার্টেনলি, এভিডেন্টলি', বলে তার কথায় সায় দেন। ইংলন্ডে মাত্র একবার ভিক্টোরিয়া আলবার্ট
আতাৎ হয়েছিল; শুনতে পাই ফ্রান্সে নাকি নিত্যি-নিত্যি, ঘরে ঘরে ।

বাড়ি ফিরে এসে বসবার ঘরে ঢুকতেই আবদুর রহমান একটা দর্শন দিয়ে গেল এবং আমি যে তার
তম্বীতেই ফিরে এসেছি, সে সম্বন্ধে আশ্বস্ত হয়ে হট করে বেরিয়ে গেল।

তখন রোজার মাস নয়, তবু আন্দাজ করলুম সেহরির সময় অর্থাৎ রাত দুটোয় খাবার জুটলে জুটতেও পারে ।

তন্দ্রা লেগে গিয়েছিল । শব্দ শুনে ঘুম ভাঙল । দেখি আবদুর রহমান মোগল তসবিরের গাড়-বদনার
সমন্বয় আফতাবে বা ধারাযন্ত্র নিয়ে সামনে দাড়িয়ে । মুখ ধুতে গিয়ে বুঝলুম, যদিও গ্রীম্মকাল, তবু
কাবুল নদীর বরফ-গলা জলে কিছুদিন ধুলে আমার মুখও আফগানিস্তানের রিলিফ ম্যাপের উঁচুনিচুর
টন্ধরের সঙ্গে সামঞ্জস্য রাখতে পারবে ।

খানা টেবিলের সামনে গিয়ে যা দেখলুম, তাতে আমার মনে আর কোনো সন্দেহ রইল না যে, আমার
ভৃত্য আগা আবদুর রহমান এককালে মেসের চার্জে ছিলেন।

ডাবর নয়, ছোটখাটো একটা গামলাভর্তি মাংসের কোরমা বা পেঁয়াজ-ঘিয়ের ঘন কৃথে সেরখানেক
দুম্বার মাংস_ তার মাঝে মাঝে কিছু বাদাম কিসমিস লুকোচুরি খেলছে, এক কোণে একটি আলু
অপাঙক্তেয় হওয়ার দুঃখে ডুবে মরার চেষ্টা করছে। আরেক প্লেটে গোটা আষ্টেক ফুল বোম্বাই সাইজের
শামী-কাবাব। বারকোশ থালায় এক ঝুড়ি কোফতা-পোলাও আর তার ওপরে বসে আছে একটি আস্ত
মুর্ি-রোস্ট |

আমাকে থ হয়ে দীড়িয়ে থাকতে দেখে আবদুর রহমান তাড়াতাড়ি এগিয়ে অভয়বাণী দিল- রান্নাঘরে
আরো আছে।

একজনের রান্না না করে কেউ যদি তিনজনের রান্না করে, তবে তাকে ধমক দেওয়া যায়, কিন্তু
সে যদি ছ'জনের রান্না পরিবেশন করে বলে রান্নাঘরে আরো আছে তখন আর কী করার থাকে? অল্প
শোকে কাতর, অধিক শোকে পাথর ।

রান্না ভালো, আমার ক্ষুধাও ছিল, কাজেই গড়পড়তা বাঙালির চেয়ে কিছু কম খাইনি । তার ওপর অদ্য
রজনী প্রথম রজনী এবং আবদুর রহমানও ডাক্তারি কলেজের ছাত্র যে রকম তনয় হয়ে মড়া কাটা দেখে,
সেই রকম আমার খাওয়ার রকম-বহর দুই-ই তার ডাবর-চোখ ভরে দেখে নিচ্ছিল ।



আমি বললুম, “ব্যস! উৎকৃষ্ট রেধেছ আবদুর রহমান_ |”

আবদুর রহমান অন্তর্ধান। ফিরে এল হাতে এক থালা ফালুদা নিয়ে। আমি সবিনয় জানালুম যে,
আমি মিষ্টি পছন্দ করি না।

আবদুর রহমান পুনরপি অন্তর্ধান। আবার ফিরে এল এক ডাবর নিয়ে-পেঁজা বরফের গুঁড়োয় ভর্তি ।

আবদুর রহমান উপরের বরফ সরিয়ে দেখাল নিচে আউুর। মুখে বলল, “বাগেবালার বরফি আঙুর-
তামাম আফগানিস্তানে মশহুর ।' বলেই একখানা সসারে কিছু বরফ আর গোটা কয়েক আঙুর নিয়ে বসল ।
আমি আঙুর খাচ্ছি, ও ততক্ষণ এক-একটা করে হাতে নিয়ে সেই বরফের টুকরোয় ঘুরিয়ে ফিরিয়ে অতি
সন্তর্পণে ঘষে-মেয়েরা যে রকম আচারের জন্য কাগজি নেবু পাথরের শিলে ঘষেন। বুঝলুম, বরফ-
ঢাকা থাকা সত্তেও আঙুর যথেষ্ট হিম হয়নি বলে এই মোলয়েম কায়দা । ওদিকে তালু আর জিবের
মাঝখানে একটা আুরে চাপ দিতেই আমার ত্রহ্মরন্ত্র পর্যন্ত ঝিনঝিন করে উঠছে। কিন্তু পাছে
আবদুর রহমান ভাবে তার মনিব নিতান্ত জংলি তাই খাইবারপাসের হিম্মৎ বুকে সঞ্চয় করে গোটা
