### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘মমতাদি’ গল্পে মমতাদির আত্মমর্যাদাবোধ কীভাবে প্রকাশ পেয়েছে?**
> 💡 **উত্তর:** গৃহপরিচারিকার কাজ করলেও মমতাদি নিজেকে দাসী মনে করেনি; সে সততা, কর্তব্যনিষ্ঠা এবং আত্মসম্মান বজায় রেখে স্নেহ-মমতার বিনিময়ে কাজ করতে চেয়েছিল।

> ❓ **প্রশ্ন: লেখকের পরিবার মমতাদিকে কীভাবে গ্রহণ করেছিল?**
> 💡 **উত্তর:** লেখকের পরিবার মমতাদিকে নিছক কাজের মানুষ হিসেবে নয়, বরং পরিবারের একজন আত্মমর্যাদাসম্পন্ন সদস্যের মতো স্নেহ ও সম্মান দিয়েছিল।
