# ১৮তম অধ্যায়: বনমানুষ (আবু ইসহাক)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: আবু ইসহাক*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : আবু ইসহাক ১৯২৬ খিষ্টাব্দের ১লা নভেম্বর শরীয়তপুর জেলার শিরঙ্গল গ্রামে জন্মগ্রহণ
করেন। তিনি আইএ পাশ করার পরই সরকারি চাকরিতে প্রবেশ করেন। ১৯৬০ সালে তিনি করাচি
বিশ্ববিদ্যালয় থেকে বিএ পরীক্ষায় উত্তীর্ণ হন। তিনি গ্রামবাংলার চিত্র এবং সেখানকার সমস্যা অত্যন্ত
সার্থকতার সঙ্গে রূপায়িত করেছেন। এদিক থেকে তার সূর্ধদীঘল বাড়ি উপন্যাসটিকে বাস্তব জীবনের
সার্থক চিত্রণের উজ্জ্বল নিদর্শন হিসেবে বিবেচনা করা যায়। উপন্যাস-সাহিত্যে অবদানের জন্য তিনি
১৯৬০ খ্রিষ্টাব্দে বাংলা একাডেমি পুরস্কার লাভ করেন । তার রচিত গ্রন্থগুলো : সূর্যদীঘল বাড়ি, হারেম, মহাপতঙ্গ,
পদ্মার পলিদ্বীপ ইত্যাদি। আবু ইসহাক ২০০৩ খ্রিষ্টাব্দের ১৭ই ফেব্রুয়ারি ঢাকায় মৃত্যুবরণ করেন |

