## 📖 মূল পাঠ (গদ্য)

বনমানুষ
আবু ইসহাক



নতুন চাকরি পেয়ে কলকাতা এসেছি। সম্পূর্ণ অস্থায়ী চাকরি। যে-কোনো সময়ে, বিনা-কারণে
ও বিনা নোটিশে বরখাস্ত হওয়ার সম্ভাবনা । নিয়োগপত্রে এসব শর্ত দেখেও ঘাবড়াইনি একটুও ।
বন-বিভাগে চাকরি করতাম ঘাট টাকায় এখানে পাব একশো তিরিশ টাকা । দ্বিগুণেরও বেশি । এমন
সুবর্ণ সুযোগ কোনো নির্বোধ পায়ে ঠেলে দেয় বলে আমার মনে হয় না। আর যাই হোক, আমি
দুপায়ে হাটি । জঙ্গলে যারা চার পায়ে হাটে, তাদের পরিবেশে থেকে আমার বুদ্ধিটা লোপ পেয়ে
যায়নি। সত্তর টাকা বেশি পাব- এ কি যেমন- তেমন ব্যাপার! বিয়ে করেছি অল্পদিন। এখন দিগুণ
আলোকে । এরকম সভ্যসমাজে আসাটাও একটা মস্ত লাভ।

চাকরিতে যোগ দিয়েছি গতকাল । আজ দ্বিতীয় দিন, বৃহস্পতিবার । নণ্টা নাবাজতেই খেয়ে নিলাম
তাড়াতাড়ি। মেসের খাওয়া । কী খেলাম বলব না, বলতে লজ্জা করে। তাছাড়া খাওয়াটা গৌণকর্ম, নেহায়েতই
রান্নাঘরের ব্যাপার । যা মুখ্য তা হচ্ছে আমাদের পোশাক । সাজ-পোশাকই আমাদের সভ্যতার মাপকাঠি
কোনোরকমে শাকভাত খেয়ে বেঁচে থাকলেও এ-দেহকে দুরস্ত খোলসে ঢেকে ভদ্রলোক সাজতেই হবে ।
তাছাড়া উপায় নেই ভদ্রসমাজে বের হওয়ার । আমাদের মতো খুদে অফিসারদের ব্যাপার আরো জটিল।
কোট-প্যান্ট পরে, টাই বেঁধে দুরস্ত হওয়া চাই, নয়তো ওপরওয়ালা সায়েবদের সুনজর হবে না
কোনোদিন । তাদের কথা : ঘোড়ায় চড়ে না হোক, গাধায় চড়েও কেন আমরা তাদের অনুসরণ
করব না? অফিসে তাই অনুকরণ ও অনুসরণের প্রতিযোগিতা বেশ উপভোগের হয়ে দীড়ায় ।

মেসের এক সদস্যের সাহায্য নিয়ে গলগ্রন্থিটা কোনোরকমে বেঁধে কোটটা গায়ে চড়িয়ে দিই।
আয়নায় মুখ দেখে ভালো লাগে না। দাড়িগুলোর কালো মাথা দেখা যাচ্ছে। অথচ গতকালই
আর-একবার ৷ তারপর জুতোজোড়া পায়ে ঢুকিয়ে আর একদফা আয়নায় মুখ দেখে বেরিয়ে পড়ি।

নস্টা বাজে। পথ সংক্ষেপ করতে গিয়ে একটা ছোট্ট গলিতে ঢুকি। গলি নয় ঠিক। দুই দেয়ালের
মাঝখান দিয়ে সরুপথ। গা বাঁচিয়ে একজন যেতে পারে কোনোমতে । মাঝপথে গিয়ে দেয়ালের
সাথে পিঠ ঠেকিয়ে দীড়াতে হয় আমাকে । একজন বুড়ো ভদ্রলোক আসছিলেন ওদিক থেকে । দেহের

ঁ
০
1


আয়তন তার নিতান্ত ছোটো নয়। তাই কোলাকুলিটা হয়ে যায় ভালোভাবেই । তারপর একজন, আরো
এক, আরো একজন । কোলাকুলি সেরে বেরিয়ে যান তারা । কোলাকুলিটা যদিও সকলের সঙ্গে সমান
বড় দুলভ।

এক ভদ্রমহিলা গলিটায় ঢুকে পড়েছেন। আমার সামান্য কয়েক কদমের পথটুকু পার হবার সুযোগ
না দিয়ে এগিয়েই আসছেন তিনি। এবার আর উপায় নেই। তাড়াতাড়ি পিছু হেঁটে শেষটায়

দেয়ালে ঠেস্‌ দেওয়ায় শ্যাওলা লেগেছিল কোটে । রুমাল বের করে ঝেড়ে আমার পথ দেখি আমি ।
এবার আর সোজাপথে নয়। সোজাপথটাই দেখছি কঠিন বেশি। বেনেপুকুর লেন ঘুরে লোয়ার

ধর্মঘটের জন্যে ট্রাম বন্ধ । আমাকে যেতে হবে ৮ নম্বর বাসে । এক এক করে কয়েকটা বাস চলে
যায়। কতবার হাতল ধরতে গিয়ে পিছিয়ে যাই। সাহসে কুলোয় না। লোকসব বাদুড়ঝোলা হয়ে
যাচ্ছে। নিরাশ হবার পাত্র আমি নই। দীড়িয়ে থাকি, দেখি অন্তত একটা পা রাখবার জায়গাও যদি
মিলে যায়।

একটা বাস এসে থামে । পা রাখবার জায়গা নেই। তবুও সব লোক ছুটোছুটি করছে, কে কার আগে
উঠবে । চাকরি ঠিক রাখার কী প্রাণান্ত চেষ্টা। একটা লোক নেমে যায় ড্রাইভারের কুঠরি থেকে।
মহাসুযোগ! পাশের কয়েকজনকে টেক্কা মেরে চট করে উঠে পড়ি আমি । চাকরি গেলে আমার চলবে না।
হঠাৎ আমার বুকে ধাক্কা মেরে একজন টেঁচিয়ে ওঠে, “মানুষ, না জানোয়ার!

লোকটা কি গণক নাকি! গণকের মতো ঠিকই তো বলেছে সে! আমি জঙ্গলেই তো ছিলাম ত্যাদ্দিন!
লোকটাকে ধন্যবাদ দেওয়ার ইচ্ছে হয়। কিন্তু সাহস হয় না। ঘাড়টা নুইয়ে গায়ে গায়ে মেশামেশি
হয়ে দীড়িয়েছি। কিন্ত মেশামেশিটা আগের কোলাকুলির মতো গ্রীতিকর হয় না। আমি শেষে ঢুকে
অনেকের অসুবিধে করেছি। ঠেলা-ধাক্কাটা তাই আমার দিকেই আসছে বেশি করে। পাঁজরের
হাড়গুলো চাপ খেতে খেতে ভেঙে যাবে মনে হচ্ছে। আর দেরি নয়। পরের স্টপে থামতেই
আমি নেমে যাই।

এতক্ষণ দম বন্ধ হয়েছিল যেন । মিনিটখানেক দাড়িয়ে শ্বাসপ্রশ্বাসকে সজীব করে নিই খোলা বাতাসে ।
স্যুটটার দিকে তাকিয়ে মায়া হয়। ভেতরের ঘামে আর ওপরের ঘষায় ইন্ত্রি ভেঙে যাচ্ছেতাই
হয়ে গেছে। এবার পাদুটোকে সম্বল করেই ছুটব ঠিক করলাম ।

কলকাতা এসেছিলাম অনেকদিন আগে একবার । পথ-ঘাট ভালো মনে নেই । পথ চেয়ে পথ চলি।
কিন্ত তার চেয়েও বেশি চেয়ে দেখতে হয় পথচারীদের পোশাকের দিকে । এই পোশাক ছাড়া কার
কী ধর্ম জানবার উপায় নেই। কারণ ধর্মের কথা গায়ে কিছু লেখা থাকে না। সব ধর্মাপরাধীদের
কারণ আমার মানুষের শরীরটাকে আত্তঃধার্মিক পোশাকে ঢেকে নিয়েছি । তাই বলে কি আমি নিরাপদ?

আন্তঃধার্মিক পোশাকে মানুষের চেহারা হলেও যে-কোনো দিকের চাকু খাওয়ার ভয় আছে আমার।
মুসলমান মোটেই না। আমার বিপদ বরং বেশি। আমাকে হিন্দু ঠাওরালে, আর হিন্দু মুসলমান
ঠাওরালেই হলো!

ভয়ে বুকটা দুরুদুরু করে। মন ইতিমধ্যে বিদ্রোহ ঘোষণা করেছে। একশো তিরিশ টাকার চাকরিটার
ভার ছেড়ে দিই পাদুটোর ওপর । শুধু তাই নয়, মনের বিরুদ্ধে সমস্ত দেহের ভারটাও ।

এক রাস্তা থেকে অন্য রাস্তায় পা দিয়ে থমকে দীড়াই। কাছাকাছি একটা প্রাণীও দেখছি না যে!
বুকের ভেতরটা দুলে ওঠে। সুমুখের একটা দোতলা বাড়ির দিকে চোখ পড়তেই দেখি, জানালা দিয়ে
মুখ বাড়িয়ে কয়েকজন কী যেন দেখছে রাস্তার দিকে। ওপর থেকে নিচের দিকে চোখ নামাতেই
চোখ ফিরে আসে, পায়ের তলা থেকে মাটি সরে যায়। গায়ের রোম কাটা দিয়ে ওঠে । চিনতে ভুল
হয় না। মানুষ! হুমড়ি খেয়ে পড়ে আছে রক্তাক্ত মানুষ । রক্তের রাঙা স্রোত ড্রেনে গিয়ে মিশেছে ।

নিমেষে পেছন ঘুরে অন্য পথ ধরি। গাড়ির আওয়াজ পেয়েও তাকাই না ফিরে। কিন্তু কে যেন
গর্জে ওঠে, 'ঠায়রো 1”

পারে না। নিয়োগপত্রটা পকেটেই ছিল। সেটা দেখিয়ে রেহাই পেয়ে যাই।

এবার আরেকটা রাস্তা ধরে হাটি। হাঁটি সুমুখে পেছনে চেয়ে। মারটা নাকি পেছন থেকেই আসে।
এক একজন লোক চলে যায় পাশ কেটে, মনে হয় এক-একটা ফীড়া কেটে যায় আমার । আমার
সতর্ক চোখদুটো আড়চোখে তাকায় সবার দিকে। কিন্তু তারাও যে সতর্কদৃষ্টি মেলে আমারই দিকে
তাকায়! আমাকে-আমার হাত দুটোকেই বোধহয় তাদের ভয়। তাদের ভীত চাউনি দেখে অনুমান
করতে কষ্ট হয় না। আমিও আমার অনুগত হাত দুটো ছাড়া আর কারো হাতকে বিশ্বাস করতে পারি না।

কিছুদূর আগে ডানদিকে একটা পাশগলি । গলির মুখে তিনটে লোক । তাদের পোশাক দেখে চমকে
উঠি। তাদের ভাবগতিকও কেমন যেন সুবিধের মনে হচ্ছে না। আমার বুকের ভেতরটা টিপটিপ
শুরু হয়েছে। আশেপাশে লোকজন নেই। পেছনে তাকিয়ে দেখি এক ত্যাংলো ইন্ডিয়ান তরুণী
উচু-গোড়ালি জুতো পায়ে আসছে গটগট করে । আমার মাথায় হঠাৎ একটা বুদ্ধি খেলে যায় । আমি
পেছন ফিরে দীড়িয়ে যাই । গলির মুখের লোকগুলোকে বোঝাতে চাই, আমি তরুণীটির জন্যেই অপেক্ষা
করছি। তারই সাথী আমি। কিন্তু তারা বুঝতে চাইলে হয়। আমার যেরকম গায়ের রং! অবশ্য
এরকম রঙের আ্যাংলো-ইন্ডিয়ানের অভাব নেই কলকাতা শহরে ।

আমার পোশাক দেখে লোকগুলো না হয় আমাকে আ্যাংলো-ইন্ডিয়ান ঠাওরাল। কিন্তু তরুণীটিকে কী
বোঝাব? আমাকে এখানে দীড়িয়ে থাকতে দেখে কী মনে করবে সে?

আমি উবু হয়ে বা-পায়ের জুতো খুলি। জুতোর ভেতর কীকর ঢুকেছে এমনি ভান করে জুতোটা উপুড়
করে ঝেড়ে নিই কয়েকবার । তারপর আবার পায়ে ঢুকাই। তরুণীটি আমার কাছে এসে গেছে।
জুতোর ফিতে বাধা শেষ করে এবার তার পাশাপাশি চলতে শুরু করি । এখন ঠিক মনে হচ্ছে- রাস্তা
দিয়ে হেটে যাচ্ছে এক আ্যাংলো-ইন্ডিয়ান দম্পতি । অন্যের কী মনে হচ্ছে জানি না। আমার কিন্তু
