### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
“স্বাধীন বাংলা বেতার'কেন্দ্র মুক্তিযোদ্ধাদের উজ্জীবিত করতে নেপথ্য ভূমিকা রেখেছিল । তারেক মাসুদ

করছেন। যুদ্ধ কেবল মুক্তিযোদ্ধারা করেনি । এ যুদ্ধে শিল্পী, কলাকুশলী ও শব্দসৈনিকের ভূমিকাও ছিল।
ক. যুদ্ধের সময় জামী কোন শ্রেণির ছাত্র ছিল?

খ. “নিয়াজীর আত্মসমর্পণ আনন্দের কিন্তু শরীফের কুলখানি বেদনার” কেন? বুঝিয়ে লেখো ।

গ. উদ্দীপকের ভাবনা “একাত্তরের দিনগুলি'র কোন দিককে উন্মোচিত করেছে? ব্যাখ্যা করো ।
ঘ. উদ্দীপকের অনুভব “একাত্তরের দিনগুলি'র সমগ্র অনুভবকে ধারণ করে কি? মূল্যায়ন করো ।

