### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘একাত্তরের দিনগুলি’ ডায়েরিভিত্তিক রচনায় কোন ঐতিহাসিক বাস্তবতার প্রতিফলন ঘটেছে?**
> 💡 **উত্তর:** ১৯৭১ সালের মহান মুক্তিযুদ্ধে পাকিস্তানি হানাদার বাহিনীর বর্বরোচিত হত্যাযজ্ঞ, অবরুদ্ধ ঢাকার ভয়াল পরিবেশ এবং শহীদ রুমীসহ মুক্তিযোদ্ধাদের বীরত্বপূর্ণ আত্মত্যাগের চিত্র ফুটে উঠেছে।

> ❓ **প্রশ্ন: শহীদ জননী জাহানারা ইমামের দেশপ্রেম কীভাবে প্রকাশ পেয়েছে?**
> 💡 **উত্তর:** নিজের প্রিয় পুত্র রুমীকে মুক্তিযুদ্ধে পাঠানো এবং চরম শোক ও আশঙ্কার মধ্যেও দেশের স্বাধীনতার পক্ষে অবিচল থাকার মধ্য দিয়ে তাঁর দেশপ্রেম চিরস্মরণীয় হয়েছে।
