বারেক : ছোটোবাবুকে বলি। স্যার একটা পোস্টার এই পিপেটাতে লাগিয়ে দিই।

নূর : কিছু দেখছ, ভালো করে দ্যাখ। বদমায়েশটার পায়ের দাগ । কাচা মাটিতে দগদগ করছে।
ছাপ নাও হতে পারে।

