### 📚 শব্দার্থ ও টীকা : গঞ্জ- ব্যবসা বাণিজ্যের স্থান, হাট। কৃষ্ণপক্ষ- চান্দ্রমাসের যে পক্ষে চন্দ্রের ক্ষয় হয়।
রাহী- পথচারী, পথিক; নজরে- দৃষ্টিতে; বেকুব-_ বেয়াকুব, বোকা। ভিন কিসিমের মাল- ভিন্ন
বা অন্য রকমের মানুষ। তেলের পিপে- তেলের ড্রাম। জালুয়া- জেলে, ধীবর। হুক্কা- কাসা পিতল
দস্তা বা মাটি অথবা নারকেল খোলে তৈরি একপ্রকার নলযুক্ত যন্ত্র যা তামাক খেতে বা
ধূমপান করতে ব্যবহৃত হয়। ধড়িবাজ- ফন্দিবাজ, প্রতারক। টহলদার- যে টহল দেয়, প্রহরী।
নুলা- বিবশ, বিকল। বেহুদা_ অনর্থক, বাজে। রোজকিয়ামত- মৃত্যুর পর পুনরুথানের দিন, শেষ
বিচারের দিন। খাস্তা- নষ্ট, পীড়িত, বিকৃত। বেদিশা- দিকভ্রষ্ট, দিশেহারা। বুহু- আত্মা, অন্তর।
তকদির- ভাগ্য, অদৃষ্ট, কপাল। নাহক- অযথা, খামখা, অনর্থক। তামাম- সমগ্র, সমস্ত, সমুদয়।
জালেম- জুলুমকারী, অত্যাচারী । গজরাতে- আক্রোশে বা ভয়ে চাপা গর্জন করা। হুজ্জত- গোলমাল,
হাঙ্গামা। জামানা_ সময়, কাল, যুগ। জীহাবাজ- দুর্দান্ত, দজ্জাল। এ্যাটেনশন- সাবধান হও।
এযাবাউট টার্ন- ঘুরে দাঁড়াও ।

