### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

মাস্টারদা সূর্য সেন বিটিশ শাসনের বিরুদ্ধে রুখে দীড়ান। এ দেশের গণমানুষকে জাগিয়ে তুলতে
নানাভাবে চেষ্টা করেন। তারই নির্দেশে টট্টগ্রামের পাহাড়তলির ইউরোপিয়ান ক্লাবে সফল
হামলার পর ব্রিটিশ শাসকদের টনক নড়ে । তাকে ধরিয়ে দেওয়ার জন্য ১০,০০০ টাকা পুরস্কার
ঘোষণা করা হয়। অর্থের লোভে জনৈক ব্যক্তি তার অবস্থান জানিয়ে দিলে তিনি ধরা পড়েন। অতঃপর

ক. 'রাহী' কথার অর্থ কী?

খ. “আমাদের সবদিকেই বিপদ'-বারেক কেন এ কথা বলেছিল?

গ. উদ্দীপকের সূর্য সেনের মাঝে “স্বাধীনতা আমার স্বাধীনতা" নাটিকার সাদৃশ্যপূর্ণ চরিত্রটি ব্যাখ্যা করো ।

