# ২১তম অধ্যায়: একুশের গল্প (জহির রায়হান)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: জহির রায়হান*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: জহির রায়হান ১৯৩৫ খিষ্টাব্দের ১৯ শে আগস্ট ফেনী জেলার মজুপুর গ্রামে জন্মগ্রহণ
করেন । তাঁর আসল নাম মোহাম্মদ জহিরুল্লাহ। ১৯৫৮ খিষ্টাব্দে তিনি ঢাকা বিশ্ববিদ্যালয় থেকে বাংলায়
স্নাতক (সম্মান) ডিগ্রি লাভ করেন। একজন ছোটগল্পকার ও ওপন্যাসিক হিসেবে জহির রায়হান খ্যাতি
অর্জন করেন। তিনি মুলত মধ্যবিত্ত জীবনের রূপকার । চারপাশের মানুষের সুখ-দুঃখ ও আনন্দ- বেদনার
উপন্যাস । বাংলাদেশের একজন খ্যাতিমান চলচ্চিত্রকার হিসেবেও জহির রায়হানের পরিচিতি রয়েছে।
স্বাধীনতাযুদ্ধে বাংলাদেশের বিজয় লাভের অল্পকাল পরেই ১৯৭২ খিষ্টাব্দের ৩০ শে জানুয়ারি তিনি নিখোঁজ
ও শহিদ হন । তাঁর লাশ পাওয়া যায়নি |

---

## 📖 মূল পাঠ (গদ্য)

একুশের গল্প



তপুকে আবার ফিরে পাবো, একথা ভুলেও ভাবি নি কোনোদিন । তবু সে আবার ফিরে এসেছে আমাদের
মাঝে । ভাবতে অবাক লাগে, চার বছর আগে যাকে হাইকোর্টের মোড়ে শেষবারের মতো দেখেছিলাম,
যাকে জীবনে আর দেখবো বলে স্বপ্নেও কল্পনা করিনি_ সেই তপু ফিরে এসেছে। ও ফিরে আসার পর
থেকে আমরা সবাই যেন কেমন একটু উদ্দিগ্ন হয়ে পড়েছি । রাতে ভালো ঘুম হয় না। যদিও একটু আধটু
তন্দ্রা আসে, তবু অন্ধকারে হঠাৎ ওর দিকে চোখ পড়লে গা হাত পা শিউরে ওঠে। ভয়ে জড়সড় হয়ে
যাই। লেপের নিচে দেহটা ঠক্ঠক্‌ করে কাপে।

দিনের বেলা ওকে ঘিরে আমরা ছোটখাটো জটলা পাকাই । খবর পেয়ে অনেকেই দেখতে আসে ওকে।
অবাক হয়ে ওর দিকে তাকিয়ে থাকে ওরা । আমরা যে অবাক হই না তা নয়। আমাদের চোখেও বিস্ময়
জাগে । দু'বছর ও আমাদের সাথে ছিল । ওর শ্বাসপ্রশ্বাসের খবরও আমরা রাখতাম । সত্যি কি অবাক কাণ্ড
দেখ তো, কে বলবে যে এ তপু । ওকে চেনাই যায় না । ওর মাকে ডাকো, আমি হলপ করে বলতে পারি,
ওর মা-ও চিনতে পারবে না ওকে।

চিনবে কী করে? জটলার একপাশ থেকে রাহাত নিজের মত বলে, চেনার কোনো উপায় থাকলে তো
চিনবে । এ অবস্থায় কেউ কাউকে চিনতে পারে না। বলে সে একটা দীর্ঘশ্বাস ছাড়ে ।

আমরাও কেমন যেন আনমনা হয়ে পড়ি ক্ষণেকের জন্য ৷ অনেক কষ্টে ঠিকানা জোগাড় করে কাল সকালে
রাহাতকে পাঠিয়েছিলাম, তপুর মা আর বউকে খবর দেবার জন্য ।

পাওয়া যায় নি তখন রীতিমতো ভাবনায় পড়লাম। এখন কী করা যায় বল তো, ওদের এক জনকেও
পাওয়া গেল না? আমি চোখ তুলে তাকালাম রাহাতের দিকে।



বিছানার ওপর ধপাস করে বসে রাহাত বললো, ওর মা মারা গেছে। মারা গেছে? আহা সেবার এখানে
গড়াগড়ি দিয়ে কী কান্নাটিই না তপুর জন্যে কেদেছিলেন তিনি । ওর কান্না দেখে আমার নিজের চোখে
পানি এসে গিয়েছিল । বউটার খবর?

ওর কথা বলো না আর । রাহাত মুখ বাকালো। অন্য আর এক জায়গায় বিয়ে করেছে। সেকি! এর মধ্যে
বিয়ে করে ফেললো মেয়েটা? তপু ওকে কত ভালোবাসতো । নাজিম বিড়বিড় করে বলে উঠলো চাপা
ম্বরে। সানু বললো, বিয়ে করবে না তো কি সারা জীবন বিধবা হয়ে থাকবে নাকি মেয়েটা । বলে তপুর
দিকে তাকালো সানু । আমরাও দৃষ্টি ফিরিয়ে আনলাম ওর ওপর ।

সত্যি, কে বলবে এ চার বছর আগেকার সেই তপু, যার মুখে এক ঝলক হাসি আঠার মতো লেগে
থাকতো সব সময়, তার দিকে তাকাতে ভয়ে আমার রক্ত হিম হয়ে আসে কেন? দু'বছর সে আমাদের
সাথে ছিলো । আমরা ছিলাম তিনজন । আমি, তপু আর রাহাত ।

তপু ছিলো আমাদের মাঝে সবার চাইতে বয়সে ছোট। কিন্তু বয়সে ছোট হলে কী হবে, ও-ই ছিলো
একমাত্র বিবাহিত। কলেজে ভর্তি হবার বছরখানেক পরে রেণুকে বিয়ে করে তপু। সম্পর্কে মেয়েটা
আত্মীয়া হতো ওর | দোহারা গড়ন, ছিপছিপে কটি , আপেল রঙের মেয়েটা প্রায়ই ওর সাথে দেখা করতে
আসতো এখানে । ও এলে আমরা চাদা তুলে চা আর মিষ্টি এনে খেতাম । আর গল্পগুজবে মেতে উঠতাম
রীতিমতো । তপু ছিল গল্পের রাজা । যেমন হাসতে পারতো ছেলেটা, তেমনি গল্প করার ব্যাপারেও ছিল
ওস্তাদ ।

যখন ও গল্প করতে শুরু করতো, তখন কাউকে কথা বলার সুযোগ দিতো না। সেই যে লোকটার কথা
তোমাদের বলেছিলাম না সেদিন। সেই হোৎকা মোটা লোকটা, ক্যাপিটালে যার সাথে আলাপ হয়েছিল,
ওই যে, লোকটা বলছিল সে বার্নাড'শ হবে, পরশু রাতে মারা গেছে একটা ছ্যাকড়া গাড়ির তলায় পড়ে ।

না? শহরের সেরা নাচিয়ে ছিলো, আজকাল অবশ্য রাজনীতি করছে। সেদিন দেখা হলো রাস্তায় । আগে
তো পাটকাঠি ছিলো । এখন বেশ মোটাসোটা হয়েছে । দেখা হতেই রেস্তোরায় নিয়ে খাওয়ালো । বিয়ে
করেছি শুনে জিজ্ঞেস করলো, বউ দেখতে কেমন হয়েছে, এবার তুমি এসো । উঃ, কথা বলতে শুরু
করলে যেন আর ফুরোতে চায় না। রাহাত থামিয়ে দিতে চেষ্টা করতো ওকে।

রেণু বলতো, আর বলবেন না, এত বক্তে পারে .....।

বলে বিরক্তিতে না লজ্জায় লাল হয়ে উঠতো সে।

তবু থামতো না তপু । এক গাল হাসি ছড়িয়ে আবার পরম্পরাহীন কথার তুবড়ি ছোটাত সে, থাকগে
অন্যের কথা যখন তোমরা শুনতে চাও না নিজের কথাই বলি। ভাবছি, ডাক্তারিটা পাশ করতে পারলে
এ শহরে আর থাকবো না, গায়ে চলে যাবো । ছোট্ট একটা ঘর বাধবো সেখানে । আর, তোমরা দেখো,
আমার ঘরে কোনো জামজমক থাকবে না । একেবারে সাধারণ, হা, একটা ছোট্ট ডিসপেনসারি আর কিছু
না। মাঝে মাঝে এমনি স্বপ্ন দেখায় অভ্যন্ত ছিল তপু । এককালে মিলিটারিতে যাবার শখ ছিল ওর।

কিন্তু বরাত মন্দ । ছিলো জন্মখোড়া ৷ ডান পা থেকে বাঁ পাটা ইঞ্চি দুয়েক ছোট ছিল ওর | তবে বা জুতোর
হিলটা একটু উচু করে তৈরি করায় দূর থেকে ওর খুঁড়িয়ে খুঁড়িয়ে চলাটা চোখে পড়তো না সবার।
আমাদের জীবনটা ছিলো যান্ত্রিক।

কাক-ডাকা ভোরে বিছানা ছেড়ে উঠতাম আমরা । তপু উঠতো সবার আগে । ও জাগাতো আমাদের
দুজনকে, ওঠো, ভোর হয়ে গেছে দেখছো না? অমন মোষের মতো ঘুমোচ্ছো কেন, ওঠো । গায়ের উপর
থেকে লেপটা টেনে ফেলে দিয়ে জোর করে আমাদের ঘুম ভাঙাতো তপু । মাথার কাছে জানালাটা খুলে
দিয়ে বলতো, দেখ বাইরে কেমন মিষ্টি রোদ উঠেছে । আর ঘুমিয়ো না, ওঠো ।

আমাদের ঘুম ভাঙিয়ে, নিজ হাতে চা তৈরি করতো তপু । চায়ের পেয়ালায় শেষ চুমুক দিয়ে আমরা বই

বিকেলটা কাটতো বেশ আমোদ-ফুর্তিতে। কোনোদিন ইস্কাটনে বেড়াতে যেতাম আমরা । কোনোদিন
বুড়িগঙ্গার ওপারে । আর যেদিন রেণু আমাদের সাথে থাকতো, সেদিন আজিমপুরের পাশ দিয়ে হাঁটতে
হাটতে দূর গায়ের ভেতর হারিয়ে যেতাম আমরা । রেণু মাঝে মাথে আমাদের জন্য ডালমুট ভেজে
আনতো বাসা থেকে । গেঁয়ো পথে হাটতে হাটতে মুড়মুড় করে ডালমুট চিবোতাম আমরা । অপু বলতো,

এই যে আঁকাবাকা লালমাটির পথ, এ পথের যদি শেষ না হতো কোনোদিন । অনন্তকাল ধরে যদি এমনি
চলতে পারতাম আমরা । একি, তুমি আবার কবি হলে কবে থেকে? ভ্রু জোড়া কুঁচকে হঠাৎ প্রশ্ন করতো
রাহাত । না, না, কবি হতে যাব কেন। ইতত্তত করে বলতো তপু । তবু কেন যেন মনে হয়........... |

স্বগ্রালু চোখে স্বগ্ন নাবতো তার । আমরা ছিলাম তিনজন । আমি, তপু আর রাহাত । দিনগুলো বেশ কাট-
ছিলো আমাদের । কিন্তু অকস্মাৎ ছেদ পড়লো । হোস্টেলের বাইরে, সবুজ ছড়ানো মাঠটাতে অগুণিত
লোকের ভিড় জমেছিলো সেদিন। ভোর হতে ক্রুদ্ধ ছেলেবুড়োরা এসে জমায়েত হয়েছিলো সেখানে ।
কয়েকটা রক্তাক্ত জামা । তর্জনী দিয়ে ওরা জামাগুলো দেখাচ্ছিলো, আর শুকনো ঠোট নেড়ে এলোমেলো
আর কী যেন বলছিলো নিজেদের মধ্যে । তপু হাত ধরে টান দিলো আমায়, এসো । কোথায়? কেন,
ওদের সাথে । চেয়ে দেখি, সমুদ্রগভীর জনতা ধীরে ধীরে চলতে শুরু করেছে। এসো । চলো । আমরা
মিছিলে পা বাড়ালাম । একটু পরে পেছন ফিরে দেখি, রেণু হাঁপাতে হাঁপাতে আমাদের দিকে ছুটে
আসছে । যা ভেবেছিলাম, দৌড়ে এসে তপুর হাত চেপে ধরলো রেণু । কোথায় যাচ্ছ তুমি । বাড়ি চলো।
পাগল নাকি, তপু হাতটা ছাড়িয়ে নিলো । তারপর বললো, তুমিও চলো না আমাদের সাথে । না, আমি
যাবো না, বাড়ি চলো । রেণু আবার হাত ধরলো ওর । কী বাজে বকছেন। রাহাত রেগে উঠলো এবার ।
বাড়ি যেতে হয় আপনি যান। ও যাবে না। মুখটা ঘুরিয়ে রাহাতের দিকে জ্জুদ্ধ দৃষ্টিতে এক পলক
তাকালো রেণু । তারপর কাঁদো কাঁদো গলায় বললো, দোহাই তোমার বাড়ি চলো । মা কাঁদছেন । বললাম
তো যেতে পারবো না, যাও । হাতটা আবার ছাড়িয়ে নিলো তপু । রেণুর করুণ মুখের দিকে তাকিয়ে মায়া
হলো । বললাম, কী ব্যাপার, আপনি এমন করছেন কেন, ভয়ের কিছু নেই, আপনি বাড়ি যান। কিছুক্ষণ
ইতস্তত করে টলটল চোখ নিয়ে ফিরে গেলো রেণু । মিছিলটা তখন মেডিকেলের গেট পেরিয়ে কার্জন
হলের কাছাকাছি এসে গেছে। তিনজন আমরা পাশাপাশি হাঁটছিলাম ।রাহাত শ্লোগান দিচ্ছিলো । আর
তপুর হাতে ছিল একটি মন্ত প্লাকার্ড। তার ওপর লাল কালিতে লেখা ছিলো, রাষ্ট্রভাষা বাংলা চাই।



মিছিলটা হাইকোর্টের মোড়ে পৌঁছতে অকস্মাৎ আমাদের সামনের লোকগ্তলো চিৎকার করে পালাতে
লাগলো চারপাশে । ব্যাপার কী বুঝবার আগেই চেয়ে দেখি, প্রাকার্ডসহ মাটিতে লুটিয়ে পড়েছে তপু।
কপালের ঠিক মাঝখানটায় গোল একটা গর্ত। আর সে গর্ত দিয়ে নির্বরের মতো রক্ত ঝরছে তার।
তপু! রাহাত আর্তনাদ করে উঠলো ।

দুজন মিলিটারি ছুটে এসে তপুর মৃতদেহটা তুলে নিয়ে গেলো আমাদের সামনে থেকে । আমরা এতটুকুও
নড়লাম না, বাধা দিতে পারলাম না । দেহটা যেন বরফের মতো জমে গিয়েছিলো, তারপর আমিও ফিরে
আসতে আসতে চিৎকার করে উঠলাম, রাহাত পালাও।

কোথায়? হতবাক হয়ে আমার দিকে তাকালো রাহাত।

তারপর উভয়ে উর্ধ্বশ্বাসে দৌড় দিলাম আমরা ইউনিভার্সিটির দিকে । সে রাতে তপুর মা এসে গড়াগড়ি
দিয়ে কেদেছিলেন এখানে । রেণুও এসেছিলো, পলকহীন চোখজোড়া দিয়ে অশ্রদর ফোয়ারা নেমেছিলো
তার । কিন্তু আমাদের দিকে একবারও তাকায় নি সে। একটা কথাও আমাদের সাথে বলেনি রেণু । রাহাত
শুধু আমার কানে ফিসফিস করে বলেছিলো, তপু না মরে আমি মরলেই ভালো হতো । কী অবাক কাগ
দেখ তো, পাশাপাশি ছিলাম আমরা । অথচ আমাদের কিছু হলো না, গুলি লাগলো কিনা তপুর কপালে
কী অবাক কাণ্ড দেখ তো।

তারপর চারটে বছর কেটে গেছে। চার বছর পর তপুকে ফিরে পাবো, একথা ভুলেও ভাবি নি
কোনোদিন । তপু মারা যাবার পর রেণু এসে একদিন মালপত্রগুলো সব নিয়ে গেলো ওর । দুটো স্যুটকেস,
একটা বইয়ের ট্রাঙ্ক, আর একটা বেডিং। সেদিনও মুখ ভার করে ছিলো রেণু।

কথা বলেনি আমাদের সাথে । শুধু রাহাতের দিকে একপলক তাকিয়ে জিজ্ঞেস করেছিলো, ওর একটা
গরম কোট ছিলো না, কোটটা কোথায়? ও, ওটা আমার স্যুটকেসে। ধীরে কোটটা বের করে দিয়েছিলো
রাহাত । এরপর দিন কয়েক তপুর সিটটা খালি পড়ে ছিলো । মাঝে মাঝে রাত শেষ হয়ে এলে আমাদের
ওঠো, আর ঘুমিও না, ওঠো ।

চোখ মেলে কাউকে দেখতে পেতাম না, শুধু ওর শূন্য বিছানার দিকে তাকিয়ে মনটা ব্যথায় ভরে উঠতো ।
তারপর একদিন তপুর সিটে নতুন ছেলে এলো একটা । সে ছেলেটা বছর তিনেক ছিলো ।

তারপর এলো আর একজন । আমাদের নতুন রুমমেট । বেশ হাসিখুশি ভরা মুখ ।

সেদিন সকালে বিছানায় বসে, “এনাটমি'র পাতা উল্টাচ্ছিলো সে । তার চৌকির নিচে একটা ঝুড়িতে রাখা
ক্ষেলিটনের' “ক্ধাল'্টা বের করে দেখছিলো আর বইয়ের সাথে মিলিয়ে পড়ছিলো সে । তারপর এক সময়
হঠাৎ রাহাতের দিকে তাকিয়ে জিজ্ঞেস করলো, রাহাত সাহেব, একটু দেখুন তো, আমার স্কালের
কপালের মাঝখানটায় একটা গর্ত কেন? কী বললে? চমকে উঠে উভয়েই তাকালাম ওর দিকে।

রাহাত উঠে গিয়ে স্কালটা তুলে নিলো হাতে । ঝুকে পড়ে সে দেখতে লাগলো অবাক হয়ে । হা, কপালের

মাঝখানটায় গোল একটা ফুটো, রাহাত তাকালো আমার দিকে, ওর চোখের ভাষা বুঝতে ভুল হলো না
আমার ।

বিড়বিড় করে বললাম, বা পায়ের হাড়টা দু'ইঞ্চি ছোট ছিলো ওর।

কথাটা শেষ না হতেই ঝুড়ি থেকে হাড়গুলো তুলে নিলো রাহাত । হাতগুলো ঠক্ঠক্‌ করে কাপছিলো
ওর । একটু

পরে উত্তেজিত গলায় চিৎকার করে বললো, বা পায়ের টিবিয়া ফেবুলাটা দু'ইঞ্চি ছোট ।

দেখো, দেখো ।

উত্তেজনায় আমিও কাপছিলাম।

ক্ষণকাল পরে স্ষালটা দুহাতে তুলে ধরে রাহাত বললো, তপু ।

