### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন

বহুনির্বাচনি প্রশ্ন
১। মানস-সংস্কৃতির সঙ্গে কোনটি সম্পর্কযুক্ত নয়?

ক. সাহিত্য খ. সংগীত

গ. শিল্প ঘ. আহারবিহার
