### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: সাহিত্যের প্রধান শাখাগুলো কী কী এবং এদের প্রধান পার্থক্য কী?**
> 💡 **উত্তর:** সাহিত্যের প্রধান শাখা হলো কবিতা, নাটক, উপন্যাস, ছোটগল্প ও প্রবন্ধ। প্রকাশের মাধ্যম, কাঠামোগত ব্যাপ্তি ও বর্ণনারীতিতে এদের মধ্যে মৌলিক পার্থক্য বিদ্যমান।

> ❓ **প্রশ্ন: ছোটগল্প ও উপন্যাসের মধ্যে মূল পার্থক্য কী?**
> 💡 **উত্তর:** উপন্যাস হলো জীবনের সামগ্রিক ও বিস্তারিত আলেখ্য, আর ছোটগল্প জীবনের একটি বিশেষ মুহূর্ত বা খণ্ডাংশের গভীর অথচ সংক্ষিপ্ত শৈল্পিক প্রকাশ।
