### 📚 শব্দার্থ ও টীকা : তত্তব শব্দ- তা থেকে উৎপন্ন, প্রাকৃত বাংলা শব্দ, এই শব্দগুলো প্রাচীন ভারতীয়
আর্ধভাষা থেকে বিভিন্ন স্তরের মাধ্যমে ক্রম পরিবর্তিত হয়ে রূপান্তর লাভ করেছে তৎসম শব্দ_
তৎসদৃশ, তদ্রুপ, সংস্কৃত শব্দের অনুরূপ বাংলা শব্দ। অর্ধ-তৎসম শব্দ_ অর্ধেক তার সমান, তৎসম
শব্দের আর্থশক পরিবর্তিত রূপ। প্রাকৃত- প্রকৃতিজাত, স্বাভাবিক, প্রাচীন ভারতীয় আর্যভাষার রূপান্তর
বিশেষ। এ-তীর্থযাত্রীরা- এখানে বাংলা ভাষায় আগত শব্দভান্ডারকে বোঝানো হয়েছে। আমাদের

সবচেয়ে প্রিয়রা- বাংলা ভাষায় আগত শব্দসমূহ আমাদের বাংলা ভাষাকে সমৃদ্ধ করেছে। একারণে
আগত শব্দসমূহকে লেখক সবচেয়ে প্রিয় বলে বিশেষায়িত করেছেন। অবিকশিতভাবে- বিকশিত নয়,
এমন। বিকলাঙ্গ_ ত্রুটিযুক্ত অঙ্গ।

