### 📚 শব্দার্থ ও টীকা

গ্রাফিতি-দেয়ালে আকা ছবি বা কথা, যা সময়ের চিত্র তুলে ধরে । চিরাচরিত- অতি প্রাচীনকাল থেকে চলে
আসছে এমন। উৎ্কণ্ঠা- উদ্বেগ; আশঙ্কা; ব্যাকুলতা । গণভবন- বাংলাদেশের প্রধানমন্ত্রীর সরকারি
বাসভবন । মুলোৎপাটন- মূলোচ্ছেদ; সমূলে বিনাশ; শিকড় সমেত তুলে ফেলা । ফ্যাসিবাদ_ ইতালির
কারফিউ - সান্ধ্যআইন; সন্ধ্যার সময় বা সন্ধ্যার পরে লোক চলাচলের নিয়ম-কানুন । [ ইংরেজি ০019৬ ]
গণঅভ্যঙ্খান- গণজাগরণ । গণ আন্দোলন- যে আন্দোলনে জনসাধারণ স্বেচ্ছায় অংশগ্রহণ করে;
গণবিক্ষোভ। প্রহসন- হাস্যরসপ্রধান নাটক; ব্যঙ্গ; বিদ্রুপ । অভূতপূর্ব- যা পূর্বে হয়নি বা ঘটেনি এমন।
সর্বজনীন- সর্বসাধারণের জন্য অনুষ্ঠিত; বারোয়ারী; সকলের জন্য মঙগলকর বা কল্যাণকর । সহিষ্ক্ঁ-
সহনশীল; বরদাপ্তকারী; ধৈর্যধারণকারী; ধৈর্যশীল ।

