### 📝 পাঠ পরিচিতি

বাংলাদেশের মানুষের রাজনৈতিক অধিকার আদায়ের সংগ্রামে জুলাই গণঅভ্যুত্থান এক নতুন মাত্রা যোগ
করেছে। এই গণঅভ্যুথান ১৯৬৯ বা ১৯৯০ থেকে পৃথক । এটা কোনো রাজনৈতিক দলের নেতৃত্বে
হয়নি। তৰু ফ্যাসিবাদী সরকারের বিপক্ষের সকল রাজনৈতিক দল এতে অংশগ্রহণ করেছিল। এর
দাবিনামার মধ্যে প্রাথমিক পর্যায়ে রাজনৈতিক কোনো দাবিও অন্তর্ভূক্ত ছিল না। ছাত্রসমাজ তাদের

শিক্ষাজীবন শেষে ন্যায্যতার ভিত্তিতে কর্মজীবনে প্রবেশের ক্ষেত্রে বাধা নিরসনের জন্য কোটাব্যবস্থার
সংস্কার চেয়েছিল। অনেক অত্যাচার-নির্যাতনের পর এই দাবি মেনে নেওয়া হলেও কৌশলে তা আবার
ফিরিয়ে আনা হয়। ফলে শিক্ষার্থীরা আবারও আন্দোলনে যেতে বাধ্য হয়। আন্দোলনের এক পর্যায়ে
সরকার চরম দমননীতি এবং হত্যাযজ্ঞ পরিচালনা করলে মানুষ স্বতঃস্ফুর্তভাবে তার প্রতিরোধে এগিয়ে
আসে। এতে গণঅভ্যু্থান ঘটে এবং সরকার-প্রধান দেশ ছেড়ে পালিয়ে যান। এই গণঅভ্যু্থান
বাংলাদেশের সকল মানুষের জন্য আবারও একটা সুন্দর দেশ নির্মাণের সুযোগ এনে দিয়েছে । একে

কর্ম-অনুশীলন

১। ১৯৬৯, ১৯৯০ এবং ২০২৪ খিষ্টাব্দের গণঅভ্যুতথানের তুলনা করে একটি সংক্ষিপ্ত প্রবন্ধ লেখো ।
(শ্রেণি-শিক্ষকের সহায়তা নিয়ে)

২। মাগো, ভাবনা কেন
তবু শত্রু এলে অস্ত্র হাতে ধরতে জানি।
তোমার ভয় নেই মা আমরা প্রতিবাদ করতে জানি ।
এই রকম উদ্দীপনামূলক €টি গানের প্রথম ৪টি করে লাইন লিখে শ্রেণি-শিক্ষকের নিকট জমা দাও ।
